{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access Block configuration, which could allow unintended public access to the bucket or its objects."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for the S3 bucket, which makes it difficult to track access requests and detect unauthorized access."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle configuration, which could lead to unnecessary storage costs if old or unused objects are not managed properly."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "logs" {
  bucket = "${local.resource_prefix.value}-logs"
  acl    = "log-delivery-write"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "${aws_kms_key.logs_key.arn}"
      }
    }
  }

  force_destroy = true

  tags = merge({
    Name        = "${local.resource_prefix.value}-logs"
    Environment = local.resource_prefix.value
  }, {})

  lifecycle_rule {
    id      = "expire-old-logs"
    enabled = true

    expiration {
      days = 90
    }
  }

  logging {
    target_bucket = "${local.resource_prefix.value}-access-logs"
    target_prefix = "${local.resource_prefix.value}/"
  }

  public_access_block {
    block_public_acls       = true
    block_public_policy     = true
    ignore_public_acls      = true
    restrict_public_buckets = true
  }
}",
  "fix_summary": "Added a Public Access Block to prevent unintended public access, enabled access logging to track bucket access, and added a lifecycle rule to manage object expiration and reduce storage costs."
}
